function asError(error: unknown): Error {
  return error instanceof Error ? error : new Error(readableMessage(error), {cause: error});
}

// JSON first so an object's own fields survive; String as the fallback for symbols and circular structures.
function readableMessage(error: unknown): string {
  if (typeof error === 'string') return error;
  try {
    const json = JSON.stringify(error);
    if (json !== undefined) return json;
  } catch {
    // Unserializable, e.g. circular: the String fallback still reads.
  }
  return String(error);
}

